import { useEffect, useState } from "react";

export default function ForecastPanel() {
  const [rows, setRows] = useState([]);

  const load = () => {
    fetch("/api/forecast-items/")
      .then(r => r.json())
      .then(d => {
        setRows(Object.entries(d).sort((a,b)=>b[1]-a[1]));
      });
  };

  useEffect(() => {
    load();
    const t = setInterval(load, 60000); // refresh every 60s
    return () => clearInterval(t);
  }, []);

  return (
    <div>
      <h2>📈 Live ML Forecast</h2>

      <table>
        <thead>
          <tr>
            <th>Item</th>
            <th>Predicted Qty</th>
          </tr>
        </thead>
        <tbody>
          {rows.map(([item,qty]) => (
            <tr key={item}>
              <td>{item}</td>
              <td>{qty}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
